def center(K, L):
    c = K.mean(0)
    return (K - c - c[:, None] + c.mean(), L - c - L.mean(1, keepdims=True) + c.mean())

def setup(p, pr):
    from scipy.spatial.distance import cdist
    (K, L) = (p['K'], p['Kq'])
    (C, M) = center(K, L)
    (e, U) = np.linalg.eigh(C)
    U = U[:, -4:]
    e = e[-4:]
    (A, B) = (U * np.sqrt(e), M @ U / np.sqrt(e))
    out = {'x': (A, B), 's': (p['sy'], p['qy']), 't': (p['st'][:, :4], p['qt'][:, :4]), 'a': (p['scores'], pr @ p['modes'].T)}
    terms = {'k': (C, M)}
    for (key, (x, q)) in out.items():
        sd = x.std(0)
        (x, q) = ((x - x.mean(0)) / sd, (q - x.mean(0)) / sd)
        (D, E) = (cdist(x, x, 'sqeuclidean'), cdist(q, x, 'sqeuclidean'))
        (P, Q) = (x @ x.T, q @ x.T)
        for deg in [1, 2, 3, 4, 5]:
            terms[key + str(deg)] = center((1 + P / len(sd)) ** deg, (1 + Q / len(sd)) ** deg)
        for w in [0.5, 1, 2, 4, 8, 16, 32]:
            terms[key + 'r' + str(w)] = center(np.exp(-D / w), np.exp(-E / w))
    return terms

def _center(k, q):
    m = k.mean(axis=0)
    g = m.mean()
    return (k - m - m[:, None] + g, q - m - q.mean(axis=1, keepdims=True) + g)

def _standardize(x, q):
    m = x.mean(axis=0)
    s = np.maximum(x.std(axis=0), 1e-10)
    return ((x - m) / s, (q - m) / s)

def _poly(x, q, degree):
    d = x.shape[1]
    return _center((1 + x @ x.T / d) ** degree, (1 + q @ x.T / d) ** degree)

def _distances(x, q):
    from scipy.spatial.distance import cdist
    return (cdist(x, x, 'sqeuclidean'), cdist(q, x, 'sqeuclidean'))
